def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    version_choices = [
        [-1] + sorted(row["version"] for row in packages[name])
        for name in names
    ]
    best_vector = None
    best_versions = None

    for vector in product(*version_choices):
        selected = dict(zip(names, vector))
        installed = {name for name, version in selected.items() if version != -1}
        if any(name not in installed or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in selected.items() if version != -1):
            continue

        rows = {}
        for name in installed:
            rows[name] = next(row for row in packages[name]
                              if row["version"] == selected[name])
        edges = {name: [] for name in installed}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = selected.get(other, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        visiting, finished = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in edges):
            continue

        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(edges[name])
        if closure != installed:
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: selected[name] for name in names
                             if selected[name] != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


